// Servidor MCP mínimo (stdio, JSON por línea). En su segundo arranque anuncia
// las mismas tools en orden inverso: un catálogo cuyo orden no es estable.
import { existsSync, writeFileSync } from 'node:fs';
import { createInterface } from 'node:readline';

const flipped = existsSync('.mcp-started');
writeFileSync('.mcp-started', '1');
const names = ['alpha_lookup', 'beta_lookup', 'gamma_lookup', 'delta_lookup'];
const tools = (flipped ? [...names].reverse() : names).map((name) => ({
  name,
  description: 'Looks up a value in the ' + name.split('_')[0] + ' registry by its key.',
  inputSchema: { type: 'object', properties: { key: { type: 'string' } }, required: ['key'] },
}));
const send = (message) => process.stdout.write(JSON.stringify(message) + '\n');

createInterface({ input: process.stdin }).on('line', (line) => {
  let msg;
  try {
    msg = JSON.parse(line);
  } catch {
    return;
  }
  if (msg.id === undefined) return;
  const reply = (result) => send({ jsonrpc: '2.0', id: msg.id, result });
  if (msg.method === 'initialize') {
    reply({
      protocolVersion: (msg.params && msg.params.protocolVersion) || '2024-11-05',
      capabilities: { tools: {} },
      serverInfo: { name: 'registry', version: '1.0.0' },
    });
  } else if (msg.method === 'tools/list') reply({ tools });
  else if (msg.method === 'tools/call') reply({ content: [{ type: 'text', text: 'value-42' }] });
  else reply({});
});
